{"code":"def transform(grid):
    h,w=len(grid),len(grid[0])
    keep=set()
    # horizontal and vertical complete border-to-border lines
    for r in range(h):
        if all(grid[r][c] != 0 for c in range(w)):
            keep.update((r,c) for c in range(w))
    for c in range(w):
        if all(grid[r][c] != 0 for r in range(h)):
            keep.update((r,c) for r in range(h))
    # diagonals whose contiguous path runs from one boundary to another
    for dr,dc in ((1,1),(1,-1)):
        for r in range(h):
            for c in range(w):
                pr,pc=r-dr,c-dc
                if 0<=pr<h and 0<=pc<w: continue
                cells=[]; rr,cc=r,c
                while 0<=rr<h and 0<=cc<w:
                    cells.append((rr,cc)); rr+=dr; cc+=dc
                if len(cells)>=2 and all(grid[x][y] != 0 for x,y in cells):
                    keep.update(cells)
    return [[grid[r][c] if (r,c) in keep else 0 for c in range(w)] for r in range(h)]"}

